package ai.taskforge.service;
import ai.taskforge.api.ApiException; import ai.taskforge.domain.*; import ai.taskforge.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class WorkflowExecutionService { private final WorkflowRepository workflows;private final WorkflowStepRepository steps;private final WorkflowInstanceRepository instances;private final TaskRepository tasks;private final UserRepository users;private final ApprovalRepository approvals;private final NotificationService notifications;private final AuditService audit;public WorkflowExecutionService(WorkflowRepository w,WorkflowStepRepository s,WorkflowInstanceRepository i,TaskRepository t,UserRepository u,ApprovalRepository a,NotificationService n,AuditService log){workflows=w;steps=s;instances=i;tasks=t;users=u;approvals=a;notifications=n;audit=log;} @Transactional public WorkflowInstance start(UUID workflowId,UUID taskId,AppUser actor){var workflow=workflows.findById(workflowId).orElseThrow(()->new ApiException("NOT_FOUND","Workflow not found."));if(!workflow.isActive())throw new ApiException("WORKFLOW_INACTIVE","This workflow is inactive.");if(instances.existsByWorkflowIdAndTaskIdAndStatus(workflowId,taskId,WorkflowInstanceStatus.ACTIVE))throw new ApiException("WORKFLOW_ALREADY_ACTIVE","This task already has an active instance of this workflow.");var task=tasks.findById(taskId).orElseThrow(()->new ApiException("NOT_FOUND","Task not found."));var flowSteps=steps.findByWorkflowIdOrderByStepOrder(workflowId);if(flowSteps.isEmpty())throw new ApiException("WORKFLOW_EMPTY","A workflow needs at least one step.");var instance=new WorkflowInstance(workflow,task);instance.moveTo(flowSteps.getFirst().getStepOrder());instance=instances.save(instance);enterStep(instance,flowSteps.getFirst(),actor);audit.record(actor,"WORKFLOW_STARTED","WORKFLOW_INSTANCE",instance.getId(),null,workflow.getName());return instance;} @Transactional public WorkflowInstance advance(UUID instanceId,AppUser actor){var instance=instances.findById(instanceId).orElseThrow(()->new ApiException("NOT_FOUND","Workflow instance not found."));if(instance.getStatus()!=WorkflowInstanceStatus.ACTIVE)throw new ApiException("WORKFLOW_CLOSED","This workflow is no longer active.");var flowSteps=steps.findByWorkflowIdOrderByStepOrder(instance.getWorkflow().getId());var current=flowSteps.stream().filter(s->s.getStepOrder()==instance.getCurrentStepOrder()).findFirst().orElseThrow(()->new ApiException("WORKFLOW_INVALID","Current workflow step is missing."));if(current.isApprovalRequired()&&!approvals.existsByTaskIdAndStatus(instance.getTask().getId(),ApprovalStatus.APPROVED))throw new ApiException("APPROVAL_REQUIRED","Approve the task before advancing this workflow.");var next=flowSteps.stream().filter(s->s.getStepOrder()>current.getStepOrder()).findFirst();if(next.isEmpty()){instance.complete();notifications.send(instance.getTask().getAssignee()==null?actor:instance.getTask().getAssignee(),"WORKFLOW_COMPLETED","Workflow completed for: "+instance.getTask().getTitle());audit.record(actor,"WORKFLOW_COMPLETED","WORKFLOW_INSTANCE",instance.getId(),"ACTIVE","COMPLETED");return instances.save(instance);}instance.moveTo(next.get().getStepOrder());enterStep(instance,next.get(),actor);audit.record(actor,"WORKFLOW_ADVANCED","WORKFLOW_INSTANCE",instance.getId(),current.getName(),next.get().getName());return instances.save(instance);} private void enterStep(WorkflowInstance instance,WorkflowStep step,AppUser actor){var role=parseRole(step.getAssigneeRole());var recipients=users.findByRole(role);if(recipients.isEmpty())recipients=List.of(actor);for(var recipient:recipients)notifications.send(recipient,"WORKFLOW_STEP","Workflow step '"+step.getName()+"' is ready for: "+instance.getTask().getTitle());if(step.isApprovalRequired()){var approver=recipients.getFirst();approvals.save(new Approval(instance.getTask(),actor,approver,"Workflow approval: "+step.getName()));}} private Role parseRole(String input){try{return input==null||input.isBlank()?Role.MANAGER:Role.valueOf(input.toUpperCase());}catch(IllegalArgumentException e){return Role.MANAGER;}} }
